-- Analytics is a read model. No duplicate attempt, mastery, readiness or schedule truth.
create function private.analytics_context(p_slug text,p_filters jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare w public.workspaces%rowtype;today date;first_day date;last_day date;span integer;r text:=coalesce(p_filters->>'range','30d');g text:=coalesce(p_filters->>'granularity','auto');begin
 w:=private.revision_access(p_slug);today:=(now() at time zone w.timezone)::date;
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>4000 then raise exception 'Invalid analytics filters' using errcode='22023';end if;
 if r not in ('7d','30d','90d','month','custom') or g not in ('auto','day','week','month') or coalesce(p_filters->>'difficulty','all') not in ('all','easy','medium','hard','unspecified') or coalesce(p_filters->>'mode','all') not in ('all','practice','interview','oa') or coalesce(p_filters->>'questionType','all') not in ('all','coding','objective','behavioral') or coalesce(p_filters->>'sessionType','all') not in ('all','initial','revision','mock') or coalesce(p_filters->>'cohort','coding') not in ('coding','objective','behavioral') then raise exception 'Unsupported analytics filters' using errcode='22023';end if;
 if length(coalesce(p_filters->>'track','all'))>200 or length(coalesce(p_filters->>'topic','all'))>200 or coalesce(p_filters->>'track','all')!~'^[a-z0-9][a-z0-9-]*$' or coalesce(p_filters->>'topic','all')!~'^[a-z0-9][a-z0-9-]*$' then raise exception 'Invalid analytics scope' using errcode='22023';end if;
 if r='custom' then first_day:=(p_filters->>'from')::date;last_day:=(p_filters->>'to')::date;
 else last_day:=case when r='month' and extract(day from today)=1 then today else today-1 end;first_day:=case r when '7d' then last_day-6 when '90d' then last_day-89 when 'month' then date_trunc('month',today)::date else last_day-29 end;end if;
 span:=last_day-first_day+1;if first_day is null or last_day is null or span not between 1 and 366 or last_day>today or first_day<date '2000-01-01' then raise exception 'Choose a past or current range of 1 to 366 days' using errcode='22023';end if;
 if g='auto' then g:=case when span<=14 then 'day' when span<=120 then 'week' else 'month' end;end if;
 if g='day' and span>90 then g:='week';end if;
 return jsonb_build_object('workspace',jsonb_build_object('id',w.id,'slug',w.slug,'name',w.name,'userId',(select auth.uid()),'timezone',w.timezone,'canEdit',w.status='active'),'from',first_day,'to',last_day,'fromAt',first_day::timestamp at time zone w.timezone,'toAt',least((last_day+1)::timestamp at time zone w.timezone,now()),'previousFrom',first_day-span,'previousTo',first_day-1,'previousFromAt',(first_day-span)::timestamp at time zone w.timezone,'days',span,'partial',last_day=today,'granularity',g,'asOf',now(),'policyVersion','analytics-policy-v1','timingPolicyVersion','timing-analytics-v1','filters',p_filters);
end $$;

create function private.analytics_activity(p_slug text,p_filters jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb;result jsonb;planning_available boolean;begin c:=private.analytics_context(p_slug,p_filters);
 planning_available:=coalesce(p_filters->>'difficulty','all')='all' and coalesce(p_filters->>'mode','all')='all' and coalesce(p_filters->>'questionType','all')='all' and coalesce(p_filters->>'sessionType','all')='all';
 with source_rows as materialized(select * from private.analytics_attempt_rows(c,'focus')),
 f as materialized(select fx.started_at,fx.ended_at,s.task_id,s.task_type,fx.item_id from public.execution_focus_intervals fx join source_rows q on q.item_id=fx.item_id join public.execution_sessions s on s.id=fx.session_id where fx.workspace_id=(c->'workspace'->>'id')::uuid and fx.user_id=(select auth.uid()) and not q.invalid and q.duration_ms>0 and fx.started_at<(c->>'toAt')::timestamptz and fx.ended_at>(c->>'fromAt')::timestamptz order by fx.started_at desc limit 100001),
 day_intervals as materialized(select dd::date as day,f.task_type,f.task_id is not null planned,tstzrange(greatest(f.started_at,dd::date::timestamp at time zone (c->'workspace'->>'timezone'),(c->>'fromAt')::timestamptz),least(f.ended_at,(dd::date+1)::timestamp at time zone (c->'workspace'->>'timezone'),(c->>'toAt')::timestamptz),'[)') span from f cross join lateral generate_series(greatest((f.started_at at time zone (c->'workspace'->>'timezone'))::date,(c->>'from')::date)::timestamp,least((f.ended_at at time zone (c->'workspace'->>'timezone'))::date,(c->>'to')::date)::timestamp,interval '1 day') dd),
 day_ranges as(select day,range_agg(span) coverage,range_agg(span) filter(where planned) planned_coverage from day_intervals where not isempty(span) group by day),
 time_days as(select day,(select coalesce(sum(extract(epoch from upper(v)-lower(v))*1000),0) from unnest(coverage) v) focus_ms,(select coalesce(sum(extract(epoch from upper(v)-lower(v))*1000),0) from unnest(planned_coverage) v) planned_ms from day_ranges),
 type_ranges as(select task_type,range_agg(span) coverage from day_intervals where not isempty(span) group by task_type),
 types as(select task_type,(select coalesce(sum(extract(epoch from upper(v)-lower(v))*1000),0) from unnest(coverage)v) focus_ms from type_ranges),
 tasks as materialized(select p.plan_date,t.status,t.carryover_from_task_id from public.daily_plans p join public.daily_tasks t on t.daily_plan_id=p.id and t.workspace_id=p.workspace_id where p.workspace_id=(c->'workspace'->>'id')::uuid and p.plan_date between (c->>'from')::date and (c->>'to')::date and p.status<>'rest' and not exists(select 1 from public.planning_availability_overrides ro where ro.workspace_id=p.workspace_id and ro.plan_date=p.plan_date and ro.rest) and planning_available and (coalesce(p_filters->>'track','all')='all' or t.track_id=p_filters->>'track' or case t.task_type when 'dsa' then 'coding' when 'behavioral' then 'behavioral' when 'language' then 'objective' when 'aptitude' then 'objective' when 'fundamentals' then 'objective' else t.task_type end=p_filters->>'track') and (coalesce(p_filters->>'topic','all')='all' or t.topic_id=p_filters->>'topic')),
 task_days as(select plan_date,count(*) filter(where status not in ('cancelled','deferred')) planned,count(*) filter(where status='completed') completed,count(*) filter(where status in ('planned','in_progress','skipped') and plan_date<(now() at time zone (c->'workspace'->>'timezone'))::date) incomplete,count(*) filter(where status='cancelled') cancelled,count(*) filter(where status='deferred') deferred,count(*) filter(where carryover_from_task_id is not null) carryover from tasks group by plan_date),
 completions as(select (at at time zone (c->'workspace'->>'timezone'))::date as day,count(*) activities from source_rows where eligible and at>=(c->>'fromAt')::timestamptz and at<(c->>'toAt')::timestamptz group by 1),
 days as materialized(select dd::date as date,coalesce(td.focus_ms,0) focus_ms,coalesce(td.planned_ms,0) planned_focus_ms,coalesce(td.focus_ms-td.planned_ms,0) unplanned_focus_ms,coalesce(a.activities,0) activities,
 case when planning_available then coalesce(t.planned,0) end planned,case when planning_available then coalesce(t.completed,0) end completed,case when planning_available then coalesce(t.incomplete,0) end incomplete,case when planning_available then coalesce(t.cancelled,0) end cancelled,case when planning_available then coalesce(t.deferred,0) end deferred,case when planning_available then coalesce(t.carryover,0) end carryover,
 (coalesce(p.status='rest',false) or coalesce(ov.rest,false)) rest,p.id is not null has_plan
 from generate_series((c->>'from')::date::timestamp,(c->>'to')::date::timestamp,interval '1 day') dd left join time_days td on td.day=dd::date left join task_days t on t.plan_date=dd::date left join completions a on a.day=dd::date left join public.daily_plans p on p.workspace_id=(c->'workspace'->>'id')::uuid and p.plan_date=dd::date left join public.planning_availability_overrides ov on ov.workspace_id=(c->'workspace'->>'id')::uuid and ov.plan_date=dd::date),
 weeks as(select date_trunc('week',date)::date as date,sum(focus_ms) focus_ms,sum(planned) planned,sum(completed) completed from days group by 1),
 attempts as materialized(select * from private.analytics_attempt_rows(c)),reviews as materialized(select ra.* from public.revision_attempts ra join attempts a on a.id=ra.source_attempt_id where ra.workspace_id=(c->'workspace'->>'id')::uuid and ra.user_id=(select auth.uid()) and ra.reviewed_at>=(c->>'fromAt')::timestamptz and ra.reviewed_at<(c->>'toAt')::timestamptz and ra.previous_interval_days is not null),
 qualifying_reviews as(select * from reviews where schedule_reason<>'EARLY_PRACTICE_NO_ADVANCE')
 select jsonb_build_object('context',c-'filters','planningAvailable',planning_available,'planningReason',case when not planning_available then 'Difficulty, mode, question-type and session-type filters have no authoritative mapping to every planned task. Plan counts remain unavailable under these filters.' end,'planningScope','workspace-shared',
 'days',(select jsonb_agg(jsonb_build_object('date',date,'focusMs',focus_ms,'plannedFocusMs',planned_focus_ms,'unplannedFocusMs',unplanned_focus_ms,'activities',activities,'planned',planned,'completed',completed,'incomplete',incomplete,'cancelled',cancelled,'deferred',deferred,'carryover',carryover,'rest',rest,'hasPlan',has_plan) order by date) from days),
 'weeks',(select jsonb_agg(jsonb_build_object('date',date,'focusMs',focus_ms,'planned',planned,'completed',completed) order by date) from weeks),'composition',coalesce((select jsonb_agg(jsonb_build_object('type',task_type,'focusMs',focus_ms) order by focus_ms desc) from types),'[]'),
 'summary',(select jsonb_build_object('focusMs',sum(focus_ms),'plannedFocusMs',sum(planned_focus_ms),'unplannedFocusMs',sum(unplanned_focus_ms),'activeDays',count(*) filter(where focus_ms>0 or activities>0),'plannedDays',case when planning_available then count(*) filter(where planned>0 and not rest) end,'completedDays',case when planning_available then count(*) filter(where planned>0 and completed=planned and not rest) end,'restDays',count(*) filter(where rest),'planned',sum(planned),'completed',sum(completed),'incomplete',sum(incomplete),'cancelled',sum(cancelled),'deferred',sum(deferred),'carryover',sum(carryover),'rescheduled',case when planning_available then (select count(*) from public.planning_activity_events e where e.workspace_id=(c->'workspace'->>'id')::uuid and e.event_type='move' and e.created_at>=(c->>'fromAt')::timestamptz and e.created_at<(c->>'toAt')::timestamptz) end,'adherence',case when sum(planned)>=5 then sum(completed)::numeric/nullif(sum(planned),0) end) from days),
 'revision',jsonb_build_object('reviews',(select count(*) from qualifying_reviews),'independent',(select count(*) from qualifying_reviews where outcome='independent_success'),'assisted',(select count(*) from qualifying_reviews where outcome in ('minor_assistance','major_assistance')),'failed',(select count(*) from qualifying_reviews where outcome='failed_recall'),'early',(select count(*) from reviews where schedule_reason='EARLY_PRACTICE_NO_ADVANCE'),'retention',case when (select count(*) from qualifying_reviews)>=5 then (select count(*)::numeric/(select count(*) from qualifying_reviews) from qualifying_reviews where outcome='independent_success') end,
 'dueNow',(select count(*) from public.revision_items r where r.workspace_id=(c->'workspace'->>'id')::uuid and r.user_id=(select auth.uid()) and r.state in ('scheduled','snoozed') and r.due_at<=now()),'overdueNow',(select count(*) from public.revision_items r where r.workspace_id=(c->'workspace'->>'id')::uuid and r.user_id=(select auth.uid()) and r.state in ('scheduled','snoozed') and r.due_at<(now() at time zone (c->'workspace'->>'timezone'))::date::timestamp at time zone (c->'workspace'->>'timezone')),
 'progression',coalesce((select jsonb_agg(jsonb_build_object('from',x.previous_interval_days,'to',x.next_interval_days,'n',x.n)) from(select previous_interval_days,next_interval_days,count(*) n from qualifying_reviews group by 1,2)x),'[]')),
 'truncated',(select count(*) from source_rows)>20000 or (select count(*) from f)>100000) into result;return result;
end $$;

-- Normalized, private source projection. It never returns code, answers, STAR text or notes.
create function private.analytics_attempt_rows(c jsonb,p_scope text default 'completed') returns table(
 id uuid,session_id uuid,item_id uuid,title text,at timestamptz,kind text,topic_id text,topic_name text,track_id text,track_name text,pattern_id text,pattern_name text,difficulty text,mode text,session_kind text,duration_ms bigint,target_ms bigint,outcome text,confidence integer,objective boolean,correct boolean,hints integer,first_hint_ms bigint,eligible boolean,timing_eligible boolean,pending boolean,invalid boolean,entity_key text,identity_known boolean,repeated boolean
) language sql security definer set search_path='' as $$
 with base as materialized(
 select q.id,q.session_id,q.item_id,i.title,coalesce(s.completed_at,q.completed_at,q.created_at) as at,
 case when b.item_id is not null then 'behavioral' when lb.item_id is not null then 'objective' when mi.source_type='story' then 'behavioral' when mi.source_type='project' then 'project' when s.task_type in ('projects','behavioral') then s.task_type when i.language<>'text' or s.task_type in ('dsa','timed_practice') then 'coding' else 'unclassified' end kind,
 coalesce(ta.topic_id,lc.topic_id) topic_id,coalesce(t.name,'Unmapped topic') topic_name,t.track_id,tr.name track_name,coalesce(q.pattern_id,origin.pattern_id) pattern_id,pa.name pattern_name,i.difficulty,s.mode,
 case when ms.id is not null then 'mock' when rl.item_id is not null then 'revision' else 'initial' end session_kind,
 q.duration_ms,q.target_duration_ms target_ms,
 case when q.result='could_not_solve' then 'unsolved' when q.result in ('solved_small_hint','solved_major_hint') or coalesce(b.cue_level,hu.hints,0)>0 then 'assisted' when q.result='solved_independently' then 'independent' else null end outcome,
 q.confidence,lb.submitted_at is not null and lb.correct is not null objective,case when lb.submitted_at is not null then lb.correct else null end correct,coalesce(b.cue_level,hu.hints,0) hints,
 case when hu.first_at is not null then (select coalesce(sum(greatest(0,floor(extract(epoch from least(fi.ended_at,hu.first_at)-fi.started_at)*1000))),0)::bigint from public.execution_focus_intervals fi where fi.item_id=q.item_id and fi.started_at<hu.first_at and fi.ended_at is not null) end first_hint_ms,
 q.reflection_status='pending' pending,s.status not in ('completed','expired') or s.completion_reason in ('abandoned','session_invalidated') invalid,
 case when lb.item_id is not null then 'activity:'||lb.activity_id when rl.item_id is not null then 'prompt:'||ri.entity_id::text else 'prompt:'||q.item_id::text end entity_key,
 lb.item_id is not null or rl.item_id is not null or exists(select 1 from public.revision_items rr where rr.entity_id=q.item_id and rr.workspace_id=q.workspace_id and rr.user_id=q.user_id) identity_known,
 rl.item_id is not null or (lb.item_id is not null and exists(select 1 from public.learning_execution_bindings older join public.question_attempts oq on oq.item_id=older.item_id where older.workspace_id=q.workspace_id and older.user_id=q.user_id and older.activity_id=lb.activity_id and (oq.created_at,oq.id)<(q.created_at,q.id))) repeated
 from public.question_attempts q join public.execution_sessions s on s.id=q.session_id and s.workspace_id=q.workspace_id and s.user_id=q.user_id join public.execution_session_items i on i.id=q.item_id
 left join public.revision_execution_links rl on rl.item_id=q.item_id left join public.revision_items ri on ri.id=rl.revision_item_id
 left join public.question_attempts origin on origin.item_id=ri.entity_id
 left join public.execution_topic_attributions ta on ta.item_id=coalesce(ri.entity_id,q.item_id)
 left join public.learning_execution_bindings lb on lb.item_id=q.item_id left join public.learning_activities la on la.id=lb.activity_id and la.version=lb.activity_version left join public.learning_concepts lc on lc.id=la.concept_id and lc.version=la.concept_version
 left join public.behavioral_practice_bindings b on b.item_id=q.item_id
 left join public.topics t on t.id=coalesce(ta.topic_id,lc.topic_id) left join public.tracks tr on tr.id=t.track_id left join public.patterns pa on pa.id=coalesce(q.pattern_id,origin.pattern_id)
 left join lateral(select m.id from public.mock_sessions m where m.execution_session_id=s.id and m.workspace_id=q.workspace_id and m.user_id=q.user_id order by m.created_at,m.id limit 1) ms on true left join lateral(select m.source_type from public.mock_session_items m where m.execution_item_id=q.item_id and m.mock_session_id=ms.id and m.workspace_id=q.workspace_id and m.user_id=q.user_id order by m.sort_order,m.id limit 1) mi on true
 left join lateral(select max(h.level)::integer hints,min(h.revealed_at) first_at from public.execution_hint_uses h where h.item_id=q.item_id and h.workspace_id=q.workspace_id and h.user_id=q.user_id) hu on true
 where q.workspace_id=(c->'workspace'->>'id')::uuid and q.user_id=(select auth.uid()) and q.user_id=(c->'workspace'->>'userId')::uuid
 and ((p_scope='completed' and s.completed_at>=(c->>'previousFromAt')::timestamptz and s.completed_at<(c->>'toAt')::timestamptz) or (p_scope='focus' and exists(select 1 from public.execution_focus_intervals fx where fx.item_id=q.item_id and fx.workspace_id=q.workspace_id and fx.user_id=q.user_id and fx.started_at<(c->>'toAt')::timestamptz and fx.ended_at>(c->>'fromAt')::timestamptz)))
 ),filtered as materialized(select * from base x where
 (coalesce(c->'filters'->>'track','all')='all' or x.track_id=c->'filters'->>'track' or x.kind=c->'filters'->>'track')
 and (coalesce(c->'filters'->>'topic','all')='all' or coalesce(x.topic_id,'unmapped')=c->'filters'->>'topic')
 and (coalesce(c->'filters'->>'difficulty','all')='all' or x.difficulty=c->'filters'->>'difficulty')
 and (coalesce(c->'filters'->>'mode','all')='all' or x.mode=c->'filters'->>'mode')
 and (coalesce(c->'filters'->>'questionType','all')='all' or x.kind=c->'filters'->>'questionType')
 and (coalesce(c->'filters'->>'sessionType','all')='all' or x.session_kind=c->'filters'->>'sessionType') order by x.at desc,x.id desc limit 20001)
 select f.id,f.session_id,f.item_id,f.title,f.at,f.kind,f.topic_id,f.topic_name,f.track_id,f.track_name,f.pattern_id,f.pattern_name,f.difficulty,f.mode,f.session_kind,f.duration_ms,f.target_ms,f.outcome,f.confidence,f.objective,f.correct,f.hints,f.first_hint_ms,
 not f.pending and not f.invalid and (case f.kind when 'coding' then f.duration_ms>=30000 when 'objective' then f.objective when 'behavioral' then f.duration_ms>=15000 else false end) eligible,
 not f.pending and not f.invalid and f.duration_ms>0 and (case f.kind when 'coding' then f.duration_ms>=30000 and f.outcome in ('independent','assisted') when 'objective' then f.objective when 'behavioral' then f.duration_ms>=15000 and f.outcome in ('independent','assisted') else false end) timing_eligible,
 f.pending,f.invalid,f.entity_key,f.identity_known,f.repeated from filtered f
$$;

create function private.analytics_stats(p_rows jsonb) returns jsonb language sql immutable set search_path='' as $$
 with x as(select * from jsonb_to_recordset(coalesce(p_rows,'[]')) as r(eligible boolean,timing_eligible boolean,outcome text,duration_ms bigint,target_ms bigint,hints integer,first_hint_ms bigint,objective boolean,correct boolean,confidence integer,at timestamptz,repeated boolean,identity_known boolean)),s as(select count(*) n,count(*) filter(where eligible) e,count(*) filter(where timing_eligible) t,count(*) filter(where eligible and objective) o from x)
 select jsonb_build_object('n',s.n,'eligible',s.e,'independent',(select count(*) from x where eligible and outcome='independent'),'assisted',(select count(*) from x where eligible and outcome='assisted'),'unsolved',(select count(*) from x where eligible and outcome='unsolved'),'solved',(select count(*) from x where eligible and outcome in ('independent','assisted')),'timed',s.t,'totalMs',(select coalesce(sum(duration_ms),0) from x where eligible),
 'medianMs',case when s.t>=3 then (select percentile_cont(.5) within group(order by duration_ms) from x where timing_eligible) end,'meanMs',case when s.t>=3 then (select avg(duration_ms) from x where timing_eligible) end,
 'p25Ms',case when s.t>=8 then (select percentile_cont(.25) within group(order by duration_ms) from x where timing_eligible) end,'p75Ms',case when s.t>=8 then (select percentile_cont(.75) within group(order by duration_ms) from x where timing_eligible) end,'p90Ms',case when s.t>=20 then (select percentile_cont(.9) within group(order by duration_ms) from x where timing_eligible) end,
 'bestMs',(select min(duration_ms) from x where timing_eligible and outcome in ('independent','assisted') and (not objective or correct)),'recentMs',(select duration_ms from x where timing_eligible order by at desc limit 1),
 'targetMs',case when (select count(*) from x where timing_eligible and target_ms>0)>=3 then (select percentile_cont(.5) within group(order by target_ms) from x where timing_eligible and target_ms>0) end,
 'varianceMs',case when (select count(*) from x where timing_eligible and target_ms>0)>=3 then (select percentile_cont(.5) within group(order by duration_ms-target_ms) from x where timing_eligible and target_ms>0) end,'withTarget',(select count(*) from x where timing_eligible and target_ms>0),'hinted',(select count(*) from x where eligible and hints>0),
 'firstHintMs',case when (select count(*) from x where eligible and first_hint_ms is not null)>=3 then (select percentile_cont(.5) within group(order by first_hint_ms) from x where eligible and first_hint_ms is not null) end,'objectiveN',s.o,'correct',(select count(*) from x where eligible and objective and correct),
 'accuracy',case when s.o>=5 then (select count(*)::numeric/s.o from x where eligible and objective and correct) end,'independentRate',case when s.e>=5 then (select count(*)::numeric/s.e from x where eligible and outcome='independent') end,'assistedRate',case when s.e>=5 then (select count(*)::numeric/s.e from x where eligible and outcome='assisted') end,
 'confidenceN',(select count(*) from x where eligible and objective and confidence is not null),'repeats',(select count(*) from x where eligible and repeated),'untrackedIdentity',(select count(*) from x where eligible and not identity_known)) from s
$$;

create function private.analytics_core(p_slug text,p_filters jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb;result jsonb;begin c:=private.analytics_context(p_slug,p_filters);
 with all_rows as materialized(select * from private.analytics_attempt_rows(c)),r as materialized(select *,at>=(c->>'fromAt')::timestamptz current_period from all_rows where kind=coalesce(p_filters->>'cohort','coding')),
 current_rows as materialized(select * from r where current_period),prior_rows as materialized(select * from r where not current_period),
 bucket_data as materialized(select date_trunc(c->>'granularity',at at time zone (c->'workspace'->>'timezone'))::date as date,private.analytics_stats(jsonb_agg(to_jsonb(x))) stats from current_rows x group by 1),
 buckets as(select dd::date as date,coalesce(b.stats,private.analytics_stats('[]'::jsonb)) stats from generate_series(date_trunc(c->>'granularity',(c->>'from')::timestamp),date_trunc(c->>'granularity',(c->>'to')::timestamp),('1 '||(c->>'granularity'))::interval) dd left join bucket_data b on b.date=dd::date),
 topics as materialized(select coalesce(topic_id,'unmapped') id,max(topic_name) name,max(track_id) track_id,max(track_name) track_name,private.analytics_stats(jsonb_agg(to_jsonb(x))) stats from current_rows x group by coalesce(topic_id,'unmapped')),
 diffs as materialized(select difficulty,private.analytics_stats(jsonb_agg(to_jsonb(x))) stats from current_rows x group by difficulty),
 question_stats as materialized(select entity_key,max(title) title,bool_or(identity_known) identity_known,private.analytics_stats(jsonb_agg(to_jsonb(x))) stats from current_rows x where eligible group by entity_key order by max(at) desc limit 30),
 calibration as(select confidence,count(*) n,count(*) filter(where correct) correct from current_rows where eligible and objective and confidence is not null group by confidence),
 pattern_rows as(select pattern_id id,max(pattern_name) name,count(*) n,count(*) filter(where outcome='independent') independent,count(*) filter(where outcome='assisted') assisted,count(*) filter(where outcome='unsolved') unsolved from current_rows where eligible and pattern_id is not null group by pattern_id order by n desc,pattern_id limit 30),
 edge_rows as(select topic_id,max(topic_name) topic_name,pattern_id,max(pattern_name) pattern_name,count(*) n from current_rows where eligible and topic_id is not null and pattern_id is not null group by topic_id,pattern_id order by n desc,topic_id,pattern_id limit 60),
 due_topics as materialized(select ta.topic_id,count(*) n,(array_agg(ri.id order by ri.due_at,ri.id))[1] id from public.revision_items ri join public.execution_topic_attributions ta on ta.item_id=ri.entity_id where ri.workspace_id=(c->'workspace'->>'id')::uuid and ri.user_id=(select auth.uid()) and ri.state in ('scheduled','snoozed') and ri.due_at<now() group by ta.topic_id),
 stats as materialized(select private.analytics_stats(coalesce((select jsonb_agg(to_jsonb(x)) from current_rows x),'[]')) cur,private.analytics_stats(coalesce((select jsonb_agg(to_jsonb(x)) from prior_rows x),'[]')) prev)
 select jsonb_build_object('context',c-'filters','current',stats.cur,'previous',stats.prev,
 'comparison',jsonb_build_object('available',coalesce((p_filters->>'compare')::boolean,true) and not(c->>'partial')::boolean and (stats.cur->>'timed')::integer>=3 and (stats.prev->>'timed')::integer>=3 and (stats.cur->>'eligible')::integer>=5 and (stats.prev->>'eligible')::integer>=5 and (select count(distinct difficulty||':'||mode||':'||session_kind) from r where eligible)=1 and (select count(*) from all_rows)<=20000,
 'reason',case when (c->>'partial')::boolean then 'The selected period includes a partial day. Choose an earlier end date for a complete-period comparison.' when not coalesce((p_filters->>'compare')::boolean,true) then 'Comparison is off.' when (select count(*) from all_rows)>20000 then 'The source budget was reached; narrow the date range.' when (stats.cur->>'eligible')::integer<5 or (stats.prev->>'eligible')::integer<5 then 'At least five eligible attempts in each equal calendar-day period are needed.' when (stats.cur->>'timed')::integer<3 or (stats.prev->>'timed')::integer<3 then 'At least three eligible timings in each period are needed for median comparison.' when (select count(distinct difficulty||':'||mode||':'||session_kind) from r where eligible)<>1 then 'Difficulty, mode or session type is mixed. Narrow the cohort before claiming a timing change.' else 'Equal calendar-day periods with one difficulty, mode and session type. Valid long attempts are retained.' end),
 'trend',coalesce((select jsonb_agg(jsonb_build_object('date',b.date)||b.stats order by b.date) from buckets b),'[]'),
 'topics',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'trackId',t.track_id,'trackName',t.track_name,'overdue',coalesce(d.n,0),'revisionId',d.id)||t.stats order by (t.stats->>'eligible')::integer desc,t.name) from(select * from topics order by (stats->>'eligible')::integer desc,id limit 60)t left join due_topics d on d.topic_id=t.id),'[]'),'topicCount',(select count(*) from topics),'topicLimit',60,
 'difficulty',coalesce((select jsonb_agg(jsonb_build_object('difficulty',d.difficulty)||d.stats order by case d.difficulty when 'easy' then 1 when 'medium' then 2 when 'hard' then 3 else 4 end) from diffs d),'[]'),
 'points',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'sessionId',x.session_id,'itemId',x.item_id,'title',x.title,'at',x.at,'durationMs',x.duration_ms,'targetMs',x.target_ms,'result',x.outcome,'difficulty',x.difficulty,'topicId',x.topic_id,'topicName',x.topic_name,'mode',x.mode,'kind',x.kind,'hints',x.hints,'correct',x.correct,'confidence',x.confidence,'identity',case when x.repeated then 'recorded_repeat' when x.identity_known then 'first_recorded' else 'untracked' end) order by x.at) from(select * from current_rows where eligible order by at desc,id desc limit 100)x),'[]'),
 'questions',coalesce((select jsonb_agg(jsonb_build_object('entityId',q.entity_key,'title',q.title,'n',q.stats->'eligible','bestMs',q.stats->'bestMs','recentMs',q.stats->'recentMs','medianMs',q.stats->'medianMs','identity',case when q.identity_known then 'recorded' else 'untracked' end)) from question_stats q),'[]'),
 'calibration',coalesce((select jsonb_agg(jsonb_build_object('confidence',x.confidence,'n',x.n,'correct',x.correct,'accuracy',case when x.n>=5 and (stats.cur->>'confidenceN')::integer>=10 then x.correct::numeric/x.n end) order by confidence) from calibration x),'[]'),
 'patterns',coalesce((select jsonb_agg(to_jsonb(p)) from pattern_rows p),'[]'),'relations',coalesce((select jsonb_agg(jsonb_build_object('topicId',e.topic_id,'topicName',e.topic_name,'patternId',e.pattern_id,'patternName',e.pattern_name,'n',e.n)) from edge_rows e),'[]'),
 'exclusions',jsonb_build_object('pending',(select count(*) from current_rows where pending),'invalid',(select count(*) from current_rows where invalid),'short',(select count(*) from current_rows where not pending and not invalid and not eligible),'unsuccessfulTiming',(select count(*) from current_rows where eligible and not timing_eligible),'missingTarget',(select count(*) from current_rows where timing_eligible and target_ms is null),'longValid',(select count(*) from current_rows where timing_eligible and duration_ms>21600000)),
 'truncated',(select count(*) from all_rows)>20000,'latestAt',(select max(at) from current_rows where eligible),'availableCohorts',coalesce((select jsonb_agg(jsonb_build_object('kind',x.kind,'n',x.n)) from(select kind,count(*) n from all_rows where eligible and at>=(c->>'fromAt')::timestamptz group by kind)x),'[]')) into result from stats;return result;
end $$;

create function private.analytics_interviews(p_slug text,p_filters jsonb default '{}',p_limit integer default 12) returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb;mocks jsonb;session_ids uuid[];mock_state text:='empty';phases jsonb;behavioral jsonb;oa jsonb;coverage jsonb;result jsonb;begin
 c:=private.analytics_context(p_slug,p_filters);if p_limit not between 1 and 100 then raise exception 'Invalid interview evidence limit' using errcode='22023';end if;
 select coalesce(array_agg(distinct q.session_id),'{}'::uuid[]) into session_ids from private.analytics_attempt_rows(c) q where not q.invalid and q.at>=(c->>'fromAt')::timestamptz;
 begin
 with raw_candidates as materialized(select m.*,s.started_at execution_started_at,s.completed_at ended_at,s.accumulated_pause_ms,s.target_duration_seconds,s.status execution_status from public.mock_sessions m join public.execution_sessions s on s.id=m.execution_session_id and s.workspace_id=m.workspace_id and s.user_id=m.user_id
 where m.workspace_id=(c->'workspace'->>'id')::uuid and m.user_id=(select auth.uid()) and s.status in ('completed','expired') and s.completion_reason not in ('abandoned','session_invalidated') and s.completed_at>=(c->>'fromAt')::timestamptz and s.completed_at<(c->>'toAt')::timestamptz
 and (coalesce(p_filters->>'mode','all')='all' or s.mode=p_filters->>'mode') and (coalesce(p_filters->>'sessionType','all') in ('all','mock'))
 and s.id=any(session_ids)
 order by s.completed_at desc,m.id desc),
 candidates as materialized(select * from(select distinct on(execution_session_id) * from raw_candidates order by execution_session_id,created_at,id)x order by ended_at desc,id limit p_limit),
 item_groups as(select m.id,count(i.id) total,count(i.id) filter(where i.status='answered') answered,count(lb.item_id) filter(where lb.submitted_at is not null and lb.correct is not null) objective_n,count(lb.item_id) filter(where lb.submitted_at is not null and lb.correct) correct,
 coalesce(jsonb_agg(jsonb_build_object('difficulty',i.difficulty,'type',coalesce(mi.source_type,'custom')) order by i.position),'[]') profile
 from candidates m join public.execution_session_items i on i.session_id=m.execution_session_id and i.workspace_id=m.workspace_id and i.user_id=m.user_id left join lateral(select mm.source_type from public.mock_session_items mm where mm.execution_item_id=i.id and mm.mock_session_id=m.id and mm.workspace_id=m.workspace_id and mm.user_id=m.user_id order by mm.sort_order,mm.id limit 1) mi on true left join public.learning_execution_bindings lb on lb.item_id=i.id group by m.id)
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'executionId',m.execution_session_id,'title',m.title,'mode',m.mode,'at',m.ended_at,'blueprintId',m.blueprint_id,'blueprintVersion',m.blueprint_version,'policyVersion',m.evaluation_policy_version,
 'family',coalesce(m.blueprint_id,'custom')||' · v'||m.blueprint_version||' · '||m.mode||' · '||substr(md5(g.profile::text||m.policy_snapshot::text||m.evaluation_policy_version),1,8),
 'questionCount',g.total,'answered',g.answered,'durationMs',greatest(0,floor(extract(epoch from m.ended_at-m.execution_started_at)*1000)-m.accumulated_pause_ms),'targetMs',m.target_duration_seconds::bigint*1000,'objectiveN',g.objective_n,'correct',g.correct,'objectiveAccuracy',case when g.objective_n>=5 then g.correct::numeric/g.objective_n end,
 'facets',(select jsonb_agg(jsonb_build_object('dimension',d.dimension,'status',case when mr.review_snapshot->'facets'->d.dimension->>'status' in ('stable','needs_attention','developing','strong','not_evaluated','no_recent_evidence','overestimated') then mr.review_snapshot->'facets'->d.dimension->>'status' else 'not_evaluated' end,'provenance','self_reported','n',case when mr.review_snapshot->'facets'->d.dimension->>'status' in ('stable','needs_attention','developing','strong','overestimated') then 1 else 0 end)) from(values('problem_solving'),('correctness'),('complexity'),('communication'),('testing'),('speed'),('confidence'))d(dimension))) order by m.ended_at desc,m.id) ,'[]') into mocks from candidates m join item_groups g on g.id=m.id left join public.mock_reviews mr on mr.mock_session_id=m.id and mr.workspace_id=m.workspace_id and mr.user_id=m.user_id;
 if jsonb_array_length(mocks)>0 then mock_state:='ready';end if;
 exception when undefined_table then mocks:='[]';mock_state:='unavailable';end;
 -- Only sessions with recorded phase transitions are eligible for phase allocation.
 with eligible_sessions as materialized(select distinct s.id,s.started_at,s.completed_at,greatest(0,floor(extract(epoch from s.completed_at-s.started_at)*1000)-s.accumulated_pause_ms)::bigint total_ms from public.execution_sessions s where s.id=any(session_ids) and s.workspace_id=(c->'workspace'->>'id')::uuid and s.user_id=(select auth.uid()) and s.mode='interview' and s.completed_at>=(c->>'fromAt')::timestamptz and exists(select 1 from public.execution_events e where e.session_id=s.id and e.event_type='phase_changed') order by s.completed_at desc limit 200),
 events as(select s.id,'understand'::text phase,0::bigint elapsed_ms,s.started_at created_at,0 priority from eligible_sessions s union all select s.id,e.phase,e.elapsed_ms,e.created_at,1 from eligible_sessions s join public.execution_events e on e.session_id=s.id where e.event_type='phase_changed' and e.phase is not null),
 flows as(select e.*,greatest(0,least(s.total_ms,lead(e.elapsed_ms,1,s.total_ms) over(partition by e.id order by e.elapsed_ms,e.created_at,e.priority))-least(s.total_ms,e.elapsed_ms)) duration_ms from events e join eligible_sessions s on s.id=e.id)
 select coalesce(jsonb_agg(jsonb_build_object('phase',x.phase,'durationMs',x.duration_ms,'sessions',x.sessions) order by case x.phase when 'understand' then 1 when 'clarify' then 2 when 'approach' then 3 when 'implement' then 4 when 'test' then 5 else 6 end),'[]') into phases from(select phase,sum(duration_ms) duration_ms,count(distinct id) sessions from flows group by phase)x;
 begin coverage:=private.behavioral_coverage(p_slug);exception when others then coverage:=null;end;
 with b as materialized(select bp.story_id,s.title,bp.cue_level,bp.confidence,bp.clarity,bp.retold,q.duration_ms,e.completed_at as at from public.behavioral_practice_bindings bp join public.star_stories s on s.id=bp.story_id join public.question_attempts q on q.item_id=bp.item_id join public.execution_sessions e on e.id=bp.session_id
 where bp.workspace_id=(c->'workspace'->>'id')::uuid and bp.user_id=(select auth.uid()) and bp.committed and q.reflection_status='completed' and q.duration_ms>=15000 and e.status='completed' and e.completion_reason not in ('session_invalidated','abandoned') and e.completed_at>=(c->>'fromAt')::timestamptz and e.completed_at<(c->>'toAt')::timestamptz
 and coalesce(p_filters->>'track','all') in ('all','behavioral') and coalesce(p_filters->>'topic','all')='all' and coalesce(p_filters->>'difficulty','all') in ('all','unspecified') and coalesce(p_filters->>'mode','all') in ('all','practice') and coalesce(p_filters->>'questionType','all') in ('all','behavioral') and (coalesce(p_filters->>'sessionType','all')='all' or case when exists(select 1 from public.revision_execution_links rsi where rsi.item_id=q.item_id) then 'revision' else 'initial' end=p_filters->>'sessionType'))
 select jsonb_build_object('n',count(*),'stories',count(distinct story_id),'noCue',count(*) filter(where cue_level=0),'outline',count(*) filter(where cue_level=1),'fullStory',count(*) filter(where cue_level=2),'observations',coalesce((select jsonb_agg(jsonb_build_object('at',x.at,'storyId',x.story_id,'title',x.title,'cueLevel',x.cue_level,'confidence',x.confidence,'clarity',x.clarity,'durationMs',x.duration_ms,'retold',x.retold) order by x.at) from(select * from b order by at desc limit 50)x),'[]'),'coverage',coverage) into behavioral from b;
 with sessions as materialized(select s.id from public.execution_sessions s where s.workspace_id=(c->'workspace'->>'id')::uuid and s.user_id=(select auth.uid()) and s.mode='oa' and s.status in ('completed','expired') and s.completion_reason<>'session_invalidated' and s.completed_at>=(c->>'fromAt')::timestamptz and s.completed_at<(c->>'toAt')::timestamptz and s.id=any(session_ids)),
 items as(select i.*,lb.submitted_at,lb.correct from sessions s join public.execution_session_items i on i.session_id=s.id left join public.learning_execution_bindings lb on lb.item_id=i.id)
 select jsonb_build_object('n',(select count(*) from sessions),'complete',(select count(*) from sessions s where not exists(select 1 from items i where i.session_id=s.id and i.status<>'answered')),'answered',count(*) filter(where status='answered'),'unanswered',count(*) filter(where status<>'answered'),'objectiveN',count(*) filter(where submitted_at is not null and correct is not null),'correct',count(*) filter(where submitted_at is not null and correct),'accuracy',case when count(*) filter(where submitted_at is not null and correct is not null)>=5 then count(*) filter(where submitted_at is not null and correct)::numeric/nullif(count(*) filter(where submitted_at is not null and correct is not null),0) end) into oa from items;
 return jsonb_build_object('context',c-'filters','mocks',mocks,'mockState',mock_state,'mockLimit',p_limit,'phases',phases,'behavioral',behavioral,'oa',oa,'readiness',jsonb_build_object('state','unavailable','reason','There is no authoritative Readiness engine or versioned readiness snapshots in this repository. Mastery and behavioral coverage remain separate evidence sources.'),'tracker',jsonb_build_object('state','unavailable','reason','Interview tracking and project evaluation are not connected to an authoritative evidence source.'));
end $$;

create function private.analytics_history(p_slug text,p_filters jsonb,p_metric text default 'all',p_cursor jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb;result jsonb;begin c:=private.analytics_context(p_slug,p_filters);
 if p_metric not in ('all','timing','independent','assisted','objective','topic') or octet_length(coalesce(p_cursor,'{}')::text)>1000 then raise exception 'Invalid analytics evidence request' using errcode='22023';end if;
 with r as materialized(select * from private.analytics_attempt_rows(c) x where x.at>=(c->>'fromAt')::timestamptz and x.kind=coalesce(p_filters->>'cohort','coding') and x.eligible and (p_metric in ('all','topic') or p_metric='timing' and x.timing_eligible or p_metric='independent' and x.outcome='independent' or p_metric='assisted' and x.outcome='assisted' or p_metric='objective' and x.objective) and (p_cursor->>'at' is null or (x.at,x.id)<((p_cursor->>'at')::timestamptz,(p_cursor->>'id')::uuid)) order by x.at desc,x.id desc limit 31)
 select jsonb_build_object('context',c-'filters','metric',p_metric,'rows',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'sessionId',x.session_id,'itemId',x.item_id,'title',x.title,'at',x.at,'durationMs',x.duration_ms,'targetMs',x.target_ms,'result',x.outcome,'difficulty',x.difficulty,'topicId',x.topic_id,'topicName',x.topic_name,'mode',x.mode,'kind',x.kind,'hints',x.hints,'correct',x.correct,'confidence',x.confidence,'identity',case when x.repeated then 'recorded_repeat' when x.identity_known then 'first_recorded' else 'untracked' end) order by x.at desc,x.id desc) from(select * from r order by at desc,id desc limit 30)x),'[]'),'cursor',case when(select count(*) from r)>30 then(select jsonb_build_object('at',at,'id',id) from r order by at desc,id desc offset 29 limit 1) end) into result;return result;
end $$;

create function public.analytics_core(p_slug text,p_filters jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.analytics_core(p_slug,p_filters)$$;
create function public.analytics_activity(p_slug text,p_filters jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.analytics_activity(p_slug,p_filters)$$;
create function public.analytics_interviews(p_slug text,p_filters jsonb default '{}',p_limit integer default 12) returns jsonb language sql security invoker set search_path='' as $$select private.analytics_interviews(p_slug,p_filters,p_limit)$$;
create function public.analytics_history(p_slug text,p_filters jsonb,p_metric text default 'all',p_cursor jsonb default null) returns jsonb language sql security invoker set search_path='' as $$select private.analytics_history(p_slug,p_filters,p_metric,p_cursor)$$;
revoke all on function private.analytics_context(text,jsonb),private.analytics_attempt_rows(jsonb,text),private.analytics_stats(jsonb) from public,anon,authenticated,service_role;
do $$declare sig text;begin foreach sig in array array['analytics_core(text,jsonb)','analytics_activity(text,jsonb)','analytics_interviews(text,jsonb,integer)','analytics_history(text,jsonb,text,jsonb)'] loop execute 'revoke all on function private.'||sig||' from public,anon,authenticated,service_role';execute 'revoke all on function public.'||sig||' from public,anon,authenticated,service_role';execute 'grant execute on function private.'||sig||' to authenticated';execute 'grant execute on function public.'||sig||' to authenticated';end loop;end $$;
-- Scoped terminal-date access is the common path for all six analytics views.
create index analytics_attempt_terminal_time on public.question_attempts(workspace_id,user_id,completed_at desc,id desc) where reflection_status='completed';
create index analytics_session_terminal_time on public.execution_sessions(workspace_id,user_id,completed_at desc,id) where status in ('completed','expired');
